"""Deterministic, offline P14 transition corpus. All media is generated by FFmpeg.

The two splits use disjoint texture seeds, frame rates, dimensions and timings.
They are synthetic checks, not estimates of performance on camera footage.
"""

from __future__ import annotations

import hashlib
import json
import math
import random
import shutil
import subprocess
from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Any

from myzing.study.transitions import TransitionProbeError


@dataclass(frozen=True)
class GeneratedCase:
    case_id: str
    split: str
    kind: str
    seed: int
    fps: int
    width: int
    height: int
    start: float
    length: float
    variant: str = ""
    duration: float = 3.0
    version: int = 1

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, value: dict[str, Any]) -> GeneratedCase:
        if value.get("version") != 1:
            raise ValueError("unsupported generated transition case version")
        return cls(**value)

    def truth_events(self) -> list[dict[str, Any]]:
        if self.kind == "negative":
            return []
        event = {"signature": self.kind, "start_seconds": self.start,
                 "end_seconds": round(self.start + self.length, 6)}
        if self.kind == "audio_aligned_cut":
            return [{**event, "signature": "hard_cut"}, event]
        return [event]


def corpus_cases(split: str = "all") -> list[GeneratedCase]:
    if split not in {"all", "calibration", "held_out"}:
        raise ValueError(f"unknown corpus split: {split}")
    cases = []
    for name, seed, fps, width, height, start in (
        ("calibration", 110, 30, 160, 120, 1.0),
        ("held_out", 710, 24, 192, 144, 1.25),
    ):
        if split not in {"all", name}:
            continue
        specs = [
            ("hard_cut", 0, "still"), ("hard_cut", 0, "moving"),
            ("audio_aligned_cut", 0, ""),
            *(("dissolve", length, "") for length in (0.25, 0.5, 1.0)),
            *(("wipe", 0.5, direction) for direction in ("left", "right", "up", "down")),
            ("zoom_punch", 0.25, "in"), ("zoom_punch", 0.5, "in"),
            ("whip_pan", 0.5, "left"), ("whip_pan", 0.5, "right"),
            ("flash", 0.25, "white"), ("flash", 0.5, "white"),
            *(("negative", 0, motion) for motion in (
                "camera_pan", "handheld_shake", "subject_motion", "lighting_change",
                "slow_push_in", "stopped_pan", "lighting_step", "lighting_pulse",
            )),
        ]
        for index, (kind, length, variant) in enumerate(specs):
            # Quantize intervals to whole output frames; record these exact values.
            length = round(length * fps) / fps
            cases.append(GeneratedCase(
                f"{name}-{index:02d}-{kind}-{variant or 'blend'}", name, kind,
                seed + index, fps, width, height, start, length, variant,
            ))
    return cases


def _texture(path: Path, seed: int, width: int, height: int) -> None:
    """Locally authored PGM chart; seeded shapes plus smooth nonperiodic detail."""
    rng = random.Random(seed)
    waves = [(rng.uniform(0.025, 0.12), rng.uniform(0.025, 0.12),
              rng.uniform(0, 6.28)) for _ in range(5)]
    boxes = [(rng.randrange(width), rng.randrange(height), rng.randrange(15, 55),
              rng.randrange(15, 55), rng.randrange(30, 225)) for _ in range(15)]
    pixels = bytearray()
    for y in range(height):
        for x in range(width):
            value = 125 + sum(17 * math.sin(x * a + y * b + c) for a, b, c in waves)
            for bx, by, bw, bh, shade in boxes:
                if bx <= x < bx + bw and by <= y < by + bh:
                    value = shade
            pixels.append(round(max(0, min(255, value))))
    path.write_bytes(f"P5\n{width} {height}\n255\n".encode() + pixels)


def _command(case: GeneratedCase, directory: Path, ffmpeg: str) -> list[str]:
    w, h, fps = case.width, case.height, case.fps
    start, length = case.start, case.length
    command = [ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
               "-filter_complex_threads", "1"]
    for name in ("a.pgm", "b.pgm"):
        command += ["-loop", "1", "-framerate", str(fps), "-i", str(directory / name)]
    audio = (f"aevalsrc='if(between(t,{start},{start + 0.12}),"
             f"0.5*sin(2*PI*700*t),0)':s=8000:d={case.duration}")
    if case.kind != "audio_aligned_cut":
        audio = f"anullsrc=r=8000:cl=mono:d={case.duration}"
    command += ["-f", "lavfi", "-i", audio]
    normal = f"scale={w}:{h},format=yuv444p,settb=1/{fps}"
    legs = [f"[0:v]{normal}[a]", f"[1:v]{normal}[b]"]
    if case.kind in {"hard_cut", "audio_aligned_cut"}:
        if case.variant == "moving":
            legs = [f"[{i}:v]crop={w}:{h}:x='20+15*t':y=20,format=yuv444p,settb=1/{fps}[{tag}]"
                    for i, tag in enumerate(("a", "b"))]
        legs += [f"[a]trim=duration={start},setpts=PTS-STARTPTS[aa]",
                 "[aa][b]concat=n=2:v=1:a=0[v]"]
    elif case.kind in {"dissolve", "wipe", "flash"}:
        effect = {"dissolve": "fade", "wipe": f"wipe{case.variant}", "flash": "fadewhite"}[case.kind]
        legs += [f"[a][b]xfade=transition={effect}:duration={length}:offset={start}[v]"]
    elif case.kind == "whip_pan":
        # Fast translation with horizontal blur on BOTH sides of a real cut.
        cut = start + length / 2
        x = f"20+100*clip((t-{start})/{length},0,1)"
        if case.variant == "right":
            x = f"120-100*clip((t-{start})/{length},0,1)"
        legs = [f"[{i}:v]crop={w}:{h}:x='{x}':y=20,"
                f"avgblur=sizeX=19:sizeY=1:enable='between(t,{start},{start + length})',"
                f"format=yuv444p,settb=1/{fps}[{tag}]" for i, tag in enumerate(("a", "b"))]
        legs += [f"[a]trim=duration={cut},setpts=PTS-STARTPTS[aa]",
                 f"[b]trim=start={cut},setpts=PTS-STARTPTS[bb]",
                 "[aa][bb]concat=n=2:v=1:a=0[v]"]
    else:
        variant = case.variant
        if case.kind == "zoom_punch" or variant == "slow_push_in":
            progress = (f"clip((on/{fps}-{start})/{length},0,1)"
                        if case.kind == "zoom_punch" else f"on/{fps}/{case.duration}")
            effect = f"zoompan=z='1+0.4*{progress}':x='iw/2-iw/zoom/2':y='ih/2-ih/zoom/2':d=1:s={w}x{h}:fps={fps}"
        elif variant in {"camera_pan", "stopped_pan", "handheld_shake"}:
            x, y = "20+32*t", "20"
            if variant == "stopped_pan":
                x = f"20+90*clip((t-{start})/0.5,0,1)"
            if variant == "handheld_shake":
                x, y = "40+16*sin(19*t)+7*sin(31*t)", "35+12*cos(23*t)"
            effect = f"crop={w}:{h}:x='{x}':y='{y}'"
        elif variant == "subject_motion":
            # Static camera, independent moving foreground from FFmpeg's test source.
            legs = [f"testsrc2=s={w}x{h}:r={fps}:d={case.duration}[v]"]
            effect = None
        else:
            amount = {"lighting_change": "0.18*clip((T-0.5)/1.5,0,1)",
                      "lighting_step": f"0.22*gte(T,{start})",
                      "lighting_pulse": f"0.7*max(0,1-abs(T-{start + 0.25})/0.25)"}[variant]
            effect = f"scale={w}:{h},geq=lum='clip(lum(X,Y)+255*({amount}),0,255)':cb=128:cr=128"
        if effect is not None:
            legs = [f"[0:v]{effect}[v]"]
    command += ["-filter_complex", ";".join(legs), "-map", "[v]", "-map", "2:a",
                "-t", str(case.duration), "-r", str(fps), "-c:v", "libx264",
                "-threads", "1", "-preset", "ultrafast", "-crf", "16", "-pix_fmt", "yuv420p",
                "-c:a", "aac", str(directory / "clip.mp4")]
    return command


def generate_corpus(output: Path, split: str = "all", *, ffmpeg: str = "ffmpeg") -> list[Path]:
    if shutil.which(ffmpeg) is None:
        raise TransitionProbeError(f"ffmpeg executable not found: {ffmpeg}; install FFmpeg and add it to PATH")
    return [generate_case(case, output, ffmpeg=ffmpeg) for case in corpus_cases(split)]


def generate_case(case: GeneratedCase, output: Path, *, ffmpeg: str = "ffmpeg") -> Path:
    directory = output / case.case_id
    directory.mkdir(parents=True, exist_ok=True)
    for name, seed in (("a.pgm", case.seed), ("b.pgm", case.seed + 10000)):
        _texture(directory / name, seed, case.width * 2, case.height * 2)
    command = _command(case, directory, ffmpeg)
    try:
        result = subprocess.run(command, capture_output=True, timeout=60)
    except (OSError, subprocess.SubprocessError) as exc:
        raise TransitionProbeError(f"generation failed for {case.case_id}: {exc}") from exc
    if result.returncode:
        raise TransitionProbeError(f"generation failed for {case.case_id}: {result.stderr.decode(errors='replace')}")
    truth = {"version": 1, "generator": "p14-ffmpeg-v1", "case": case.to_dict(),
             "media": "clip.mp4", "sha256": hashlib.sha256((directory / "clip.mp4").read_bytes()).hexdigest(),
             "truth_events": case.truth_events(), "command": command}
    (directory / "truth.json").write_text(json.dumps(truth, indent=2) + "\n", encoding="utf-8")
    return directory
